#!/usr/bin/env python3
import json
from pathlib import Path

ROOT = Path('content/articles')

EXACT = {
    'por lo que las recomendaciones de consumo para embarazadas y niños merecen un artículo específico.':
        'por lo que el mercurio también debe tenerse en cuenta al decidir la frecuencia de consumo, aunque aquí el criterio principal sea la proteína.',
    'Eso se desarrolla mejor en artículos específicos que convertir este ranking en una lista de prohibiciones.':
        'También conviene tener en cuenta la sal y, en especies grandes como algunos atunes, el mercurio, aunque aquí el criterio principal sea la relación entre proteína y calorías.',
    'Pueden ser excelentes fuentes de proteína, pero merecen su propia categoría.':
        'Pueden ser excelentes fuentes de proteína, pero conviene compararlas por separado porque su contenido de agua es distinto.',
    'deserves its own article': 'also matters when judging the food as a whole',
    'deserve their own article': 'also matter when judging the food as a whole',
}

FORBIDDEN = [
    'merece un artículo específico', 'merecen un artículo específico',
    'merece un artículo aparte', 'merecen un artículo aparte',
    'en otro artículo', 'lo veremos aparte', 'se tratará aparte',
    'deserves its own article', 'deserve their own article',
    'in another article', 'covered elsewhere', "we'll cover", 'we will cover'
]

FISH_ES = """<p>El pescado es, en general, una fuente muy concentrada de proteína. Entre las especies habituales, la mayoría se mueve aproximadamente entre <strong>20 y 30 g de proteína por cada 100 g</strong> una vez cocinadas o, en el caso de las conservas, escurridas.</p><p>La clave para que la comparación sea útil es no convertir cada método de cocina en una categoría distinta. En esta tabla usamos una forma de consumo normal: <strong>cocinado</strong> para pescado fresco y <strong>en conserva y escurrido</strong> cuando ese es el producto habitual. Plancha, horno o vapor pueden mover algo la cifra por la cantidad de agua que se pierde, pero no cambian por completo el papel nutricional del pescado.</p><h2>Ranking sencillo de proteína por 100 g</h2><table><thead><tr><th>Pescado</th><th>Forma comparada</th><th>Proteína aprox.</th><th>Calorías aprox.</th></tr></thead><tbody><tr><td>Atún</td><td>Cocinado</td><td>29 g</td><td>130 kcal</td></tr><tr><td>Anchoas</td><td>En conserva, escurridas</td><td>29 g</td><td>210 kcal</td></tr><tr><td>Sardinas</td><td>En conserva, escurridas</td><td>25 g</td><td>208 kcal</td></tr><tr><td>Caballa</td><td>Cocinada</td><td>24 g</td><td>262 kcal</td></tr><tr><td>Trucha</td><td>Cocinada</td><td>24 g</td><td>168 kcal</td></tr><tr><td>Pez espada</td><td>Cocinado</td><td>23 g</td><td>172 kcal</td></tr><tr><td>Bacalao</td><td>Cocinado</td><td>23 g</td><td>105 kcal</td></tr><tr><td>Salmón</td><td>Cocinado</td><td>22 g</td><td>206 kcal</td></tr></tbody></table><p>Las cifras están redondeadas a partir de referencias de USDA FoodData Central. Redondearlas es deliberado: una diferencia de unas décimas no tiene utilidad práctica cuando el contenido real también cambia con la especie concreta, el tamaño de la pieza y la pérdida de agua durante la cocción.</p><h2>Atún: mucha proteína con pocas calorías</h2><p>El atún cocinado de la referencia utilizada aporta alrededor de <strong>29 g de proteína y 130 kcal por 100 g</strong>. Es una relación proteína-calorías muy alta.</p><p>Eso no significa que sea el pescado que convenga comer siempre. Algunas especies de atún son peces grandes y pueden acumular más mercurio que especies pequeñas. Para decidir la frecuencia de consumo también cuentan el tipo de atún, la variedad de pescados de la dieta y, en grupos vulnerables, las recomendaciones oficiales sobre mercurio.</p><h2>Anchoas y sardinas: muy concentradas, pero la ración suele ser menor</h2><p>Las anchoas en conserva rondan <strong>29 g de proteína por 100 g</strong> y las sardinas unos <strong>25 g</strong>. Sin embargo, 100 g de anchoas no es una ración habitual para la mayoría de personas.</p><p>Además, en las conservas hay que mirar el conjunto. Las anchoas suelen concentrar bastante sodio; las sardinas con espina comestible aportan calcio; y el aceite de cobertura aumenta la energía aunque se escurra parte.</p><h2>Caballa, trucha y salmón: proteína alta y más grasa</h2><p>Caballa, trucha y salmón siguen siendo pescados muy proteicos: aproximadamente <strong>22–24 g por 100 g</strong> en las referencias utilizadas. La diferencia frente a bacalao o atún está sobre todo en la grasa.</p><p>Por ejemplo, el bacalao cocinado ronda <strong>105 kcal por 100 g</strong>, mientras el salmón está alrededor de <strong>206 kcal</strong> y la caballa cerca de <strong>262 kcal</strong>. A cambio, salmón y caballa aportan cantidades relevantes de EPA y DHA, los omega-3 de cadena larga característicos del pescado azul.</p><h2>Bacalao: proteína parecida con muy poca grasa</h2><p>El bacalao cocinado aporta alrededor de <strong>23 g de proteína y 105 kcal por 100 g</strong>. Comparado con el salmón, la proteína es muy parecida —23 frente a 22 g—, pero las calorías son aproximadamente la mitad porque el bacalao contiene mucha menos grasa.</p><p>El bacalao salado debe considerarse aparte de esta comparación porque la salazón cambia mucho el sodio y también modifica el contenido de agua.</p><h2>¿Y si el pescado se come crudo, por ejemplo en sushi?</h2><p>El pescado crudo suele contener algo más de agua que el mismo pescado después de cocinarlo. Por eso puede mostrar menos proteína <em>por 100 g</em>, aunque la cocción no esté creando proteína: simplemente se pierde agua y los nutrientes quedan más concentrados por peso.</p><p>Si el objetivo es comparar una pieza de sashimi con otra, lo correcto sería usar valores de pescado crudo para ambas. Para una tabla general como esta, utilizar pescado cocinado y conservas escurridas refleja mejor cómo se consume habitualmente cada producto y evita mezclar estados sin explicarlo.</p><h2>¿Pescado blanco o azul tiene más proteína?</h2><p>No hay una separación clara. En esta comparación, el bacalao —pescado blanco— aporta unos <strong>23 g</strong>, mientras el salmón y la caballa —pescados azules— aportan aproximadamente <strong>22 y 24 g</strong>. La diferencia principal entre ambos grupos suele estar más en la grasa que en la proteína.</p><h2>Proteína por ración</h2><table><thead><tr><th>Ejemplo</th><th>Ración</th><th>Proteína aprox.</th></tr></thead><tbody><tr><td>Atún cocinado</td><td>150 g</td><td>44 g</td></tr><tr><td>Trucha cocinada</td><td>150 g</td><td>36 g</td></tr><tr><td>Bacalao cocinado</td><td>150 g</td><td>34 g</td></tr><tr><td>Salmón cocinado</td><td>150 g</td><td>33 g</td></tr><tr><td>Sardinas en conserva</td><td>100 g</td><td>25 g</td></tr></tbody></table><p>La diferencia entre 22 y 24 g por 100 g es pequeña en una comida normal. Por eso, después de comprobar que todos son buenas fuentes de proteína, tiene más sentido elegir también por sabor, variedad, omega-3, sal, calcio, grasa y recomendaciones de seguridad según la especie.</p><h2>Conclusión</h2><p>Si miramos solo proteína por peso, el atún y las anchoas aparecen muy arriba, alrededor de <strong>29 g por 100 g</strong>. Sardinas, caballa, trucha, pez espada, bacalao y salmón se mantienen también en cifras altas, aproximadamente entre <strong>22 y 25 g</strong>.</p><p>La forma más útil de leer el ranking no es buscar un ganador absoluto, sino entender que casi todos estos pescados cubren muy bien la función proteica. A partir de ahí, el resto del perfil nutricional y la variedad de especies son los que marcan diferencias más interesantes.</p><h2>Fuentes y criterio</h2><p>Los valores se han redondeado a partir de USDA FoodData Central y de los registros de composición ya documentados en las fuentes del artículo. La tabla distingue únicamente entre pescado cocinado y conserva escurrida para mantener una comparación comprensible; cuando una preparación altera sobre todo el agua o el sodio, se explica en el texto.</p>"""

FISH_EN = """<p>Fish is generally a very concentrated source of protein. Most common choices provide roughly <strong>20 to 30 grams of protein per 100 grams</strong> once cooked or, for canned fish, drained.</p><p>To keep the comparison useful, this article does not turn every cooking method into a separate ranking. Fresh fish is shown simply as <strong>cooked</strong>, while canned fish is shown <strong>drained</strong>. Grilling, baking, steaming or pan-cooking can shift the number slightly because they change water content, but they do not transform an ordinary fish into a completely different protein food.</p><h2>Simple protein ranking per 100 grams</h2><table><thead><tr><th>Fish</th><th>Form compared</th><th>Approx. protein</th><th>Approx. calories</th></tr></thead><tbody><tr><td>Tuna</td><td>Cooked</td><td>29 g</td><td>130 kcal</td></tr><tr><td>Anchovies</td><td>Canned, drained</td><td>29 g</td><td>210 kcal</td></tr><tr><td>Sardines</td><td>Canned, drained</td><td>25 g</td><td>208 kcal</td></tr><tr><td>Mackerel</td><td>Cooked</td><td>24 g</td><td>262 kcal</td></tr><tr><td>Trout</td><td>Cooked</td><td>24 g</td><td>168 kcal</td></tr><tr><td>Swordfish</td><td>Cooked</td><td>23 g</td><td>172 kcal</td></tr><tr><td>Cod</td><td>Cooked</td><td>23 g</td><td>105 kcal</td></tr><tr><td>Salmon</td><td>Cooked</td><td>22 g</td><td>206 kcal</td></tr></tbody></table><p>The figures are rounded from USDA FoodData Central references. Rounding is intentional: tenths of a gram are not very useful when the real value also varies with species, cut and the amount of water lost during cooking.</p><h2>Tuna: a lot of protein for relatively few calories</h2><p>The cooked tuna reference used here provides about <strong>29 g of protein and 130 calories per 100 g</strong>. That makes it highly protein-dense.</p><p>It is not automatically the fish to eat most often. Some tuna species are large predators and can accumulate more mercury than smaller fish. Frequency therefore depends on the type of tuna, the variety of fish in the diet and, for people who are pregnant or may become pregnant and for children, current FDA/EPA fish guidance.</p><h2>Anchovies and sardines: concentrated, but portions are usually smaller</h2><p>Canned anchovies provide about <strong>29 g of protein per 100 g</strong>, while sardines provide about <strong>25 g</strong>. A 100 g serving of anchovies, however, is much larger than most people normally eat.</p><p>Canned fish also needs context. Anchovies can be very high in sodium; sardines with edible bones provide calcium; and oil-packed products carry more calories even after some of the oil is drained.</p><h2>Mackerel, trout and salmon: high protein with more fat</h2><p>Mackerel, trout and salmon remain high-protein fish at roughly <strong>22–24 g per 100 g</strong> in these references. The bigger difference from cod or very lean tuna is fat.</p><p>Cooked cod is about <strong>105 calories per 100 g</strong>, compared with roughly <strong>206 calories for salmon</strong> and <strong>262 for mackerel</strong>. Salmon and mackerel also provide substantial EPA and DHA omega-3 fats.</p><h2>Cod: similar protein with very little fat</h2><p>Cooked cod provides about <strong>23 g of protein and 105 calories per 100 g</strong>. Compared with salmon, the protein is almost the same—23 versus 22 g—but the calories are roughly half because cod is much leaner.</p><p>Salt cod is a different comparison because curing dramatically changes sodium and also changes water content.</p><h2>What if you eat fish raw, such as sushi or sashimi?</h2><p>Raw fish usually contains a little more water than the same fish after cooking. It can therefore show less protein <em>per 100 g</em>, even though cooking has not created protein; water has simply been lost and the nutrients are more concentrated by weight.</p><p>If you are comparing two sashimi choices, use raw values for both. For a general ranking, cooked fish and drained canned fish better reflect the usual form in which these foods are eaten without mixing states silently.</p><h2>Does white fish have less protein than oily fish?</h2><p>Not necessarily. Cod in this comparison provides about <strong>23 g per 100 g</strong>, while salmon provides about <strong>22 g</strong> and mackerel about <strong>24 g</strong>. The clearest difference between lean and oily fish is usually fat, not protein.</p><h2>Protein per serving</h2><table><thead><tr><th>Example</th><th>Serving</th><th>Approx. protein</th></tr></thead><tbody><tr><td>Cooked tuna</td><td>150 g</td><td>44 g</td></tr><tr><td>Cooked trout</td><td>150 g</td><td>36 g</td></tr><tr><td>Cooked cod</td><td>150 g</td><td>34 g</td></tr><tr><td>Cooked salmon</td><td>150 g</td><td>33 g</td></tr><tr><td>Canned sardines</td><td>100 g</td><td>25 g</td></tr></tbody></table><p>A difference between 22 and 24 g per 100 g is small in a normal meal. Once you know these are all strong protein sources, taste, variety, omega-3 content, sodium, calcium, fat and species-specific safety guidance become more useful tie-breakers.</p><h2>Bottom line</h2><p>If protein concentration is the only metric, tuna and anchovies sit near the top at about <strong>29 g per 100 g</strong>. Sardines, mackerel, trout, swordfish, cod and salmon are also high, generally around <strong>22–25 g</strong>.</p><p>The useful conclusion is not that one species wins. Most of these fish do the protein job extremely well; the more meaningful differences come from the rest of their nutrition profile and from eating a variety of species.</p><h2>Sources and method</h2><p>Values are rounded from USDA FoodData Central and the composition references already listed in the article sources. The table uses only two reader-friendly states—cooked fish and drained canned fish—and explains separately when preparation mainly changes water, sodium or calories.</p>"""


def walk_clean(value):
    if isinstance(value, str):
        out = value
        for old, new in EXACT.items():
            out = out.replace(old, new)
        return out
    if isinstance(value, list):
        return [walk_clean(v) for v in value]
    if isinstance(value, dict):
        return {k: walk_clean(v) for k, v in value.items()}
    return value


def main():
    paths = sorted(ROOT.glob('es/*.json')) + sorted(ROOT.glob('en/*.json'))
    if len(paths) != 50:
        raise SystemExit(f'Expected 50 article JSON files, found {len(paths)}')
    for path in paths:
        data = walk_clean(json.loads(path.read_text(encoding='utf-8')))
        if data.get('article_number') == 14 and data.get('language') == 'es':
            data['excerpt'] = 'El atún ronda 29 g de proteína por 100 g, pero sardinas, caballa, trucha, bacalao y salmón también son fuentes muy concentradas. La comparación usa estados sencillos —cocinado o en conserva— y explica aparte cómo el agua, la grasa, la sal y el mercurio cambian la interpretación.'
            data['content_html'] = FISH_ES
            data['faq'] = [
                {'question':'¿Qué pescado tiene más proteína?','answer':'En las referencias comparadas, el atún cocinado y las anchoas en conserva rondan 29 g por 100 g. Sardinas, caballa, trucha, pez espada, bacalao y salmón se sitúan aproximadamente entre 22 y 25 g.'},
                {'question':'¿El salmón tiene menos proteína que el atún?','answer':'Sí en estas referencias: unos 22 g/100 g frente a 29 g/100 g del atún. El salmón aporta más grasa y omega-3, por lo que el ranking de proteína no resume todo su valor nutricional.'},
                {'question':'¿Cambia la proteína si el pescado se cocina a la plancha o al horno?','answer':'Puede cambiar ligeramente por la pérdida de agua. La cocción no crea proteína; al perder humedad, la proteína queda más concentrada por cada 100 g.'},
                {'question':'¿El pescado blanco tiene menos proteína?','answer':'No necesariamente. El bacalao cocinado ronda 23 g/100 g, prácticamente lo mismo que muchos pescados azules. La principal diferencia suele estar en la grasa.'}
            ]
        elif data.get('article_number') == 14 and data.get('language') == 'en':
            data['excerpt'] = 'Tuna is near 29 g of protein per 100 g, but sardines, mackerel, trout, cod and salmon are also highly concentrated sources. The comparison keeps preparation simple—cooked or canned—and explains separately how water, fat, sodium and mercury affect the bigger picture.'
            data['content_html'] = FISH_EN
            data['faq'] = [
                {'question':'Which fish has the most protein?','answer':'In the references compared here, cooked tuna and canned anchovies are around 29 g per 100 g. Sardines, mackerel, trout, swordfish, cod and salmon are generally around 22–25 g.'},
                {'question':'Does salmon have less protein than tuna?','answer':'In these references, yes: about 22 g/100 g for salmon versus 29 g/100 g for tuna. Salmon also contains more fat and long-chain omega-3s, so protein is only one part of the comparison.'},
                {'question':'Does grilling or baking change the protein number?','answer':'It can shift the value slightly by changing water content. Cooking does not create protein; losing moisture simply concentrates protein per 100 g.'},
                {'question':'Does white fish have less protein?','answer':'Not necessarily. Cooked cod is around 23 g/100 g, very similar to many oily fish. Fat content usually differs more than protein.'}
            ]
        text = json.dumps(data, ensure_ascii=False, indent=2) + '\n'
        path.write_text(text, encoding='utf-8')

    hits = []
    for path in paths:
        text = path.read_text(encoding='utf-8').lower()
        for phrase in FORBIDDEN:
            if phrase.lower() in text:
                hits.append((path, phrase))
    if hits:
        for path, phrase in hits:
            print(f'FORBIDDEN {path}: {phrase}')
        raise SystemExit('Self-contained article audit failed')
    print('CLEANED_ARTICLES=50')
    print('SELF_CONTAINED_ARTICLE_AUDIT=PASS')

if __name__ == '__main__':
    main()
